void rotateScannedDropdown(int diff)
{
    if (diff != 0)
    {
        // Get the current selected index
        int current_index = lv_dropdown_get_selected(ui_curDropdownList);
        
        // Get the total number of options
        const char *options = lv_dropdown_get_options(ui_curDropdownList);
        int total_options = 0;
        
        // Count the number of options by counting '\n' occurrences
        for (const char *p = options; *p; p++)
        {
            if (*p == '\n') total_options++;
        }
        total_options++; // Add one for the last option (no '\n' at the end)
        
        // Update index based on rotation direction
        int new_index = current_index + diff;
        
        // Ensure index stays within valid bounds
        if (new_index < 0) 
        new_index = total_options - 1; // Wrap around to the last item
        else if (new_index >= total_options) 
        new_index = 0; // Wrap around to the first item
        
        // Set new selected index
        lv_dropdown_set_selected(ui_curDropdownList, new_index);
    } 
}

void ui_event_devNameEvents(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_PRESSED)
    {
        memcpy(&btDevice, (ScannedDevice*)lv_event_get_user_data(e), sizeof(btDevice));
        btAudio.connect_to_bt_device(btDevice.name);
        btMode = CONNECTING;
        syncBtScreen(true);
    }
    else if(event_code == LV_EVENT_RELEASED)
    {
        btMode = IDLE;
    }
    else
        return;

    controlScreen = NULL;
    _ui_screen_change(&ui_BluetoothScreen, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_BluetoothScreen_screen_init);
}

void checkBtDeviceConnectivity()
{
    if(!(lv_obj_has_flag(ui_Spinner, LV_OBJ_FLAG_HIDDEN)) && xQueueReceive(xQueueDevData, &gotDevices, (TickType_t) 1))
    {
        lv_group_remove_all_objs(EnableBtGroup);
        ESP_LOGD(TAG, "Queue Received\n");
        _ui_flag_modify(ui_Spinner, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        if (btAudio.scanned_device_count == 0) {
            ESP_LOGD(TAG, "No devices found.\n");
            lv_label_set_text_fmt(ui_btScanLbl, "%s", "No devices found!");
            lv_obj_set_pos(ui_btScanLbl, 0, 65);
            _ui_flag_modify(ui_TryAgainBtnCntr, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
            lv_group_add_obj(EnableBtGroup, ui_TryAgainBtnCntr);
            lv_group_focus_obj(ui_TryAgainBtnCntr);
            return;
        }

        lv_group_remove_all_objs(EnableBtGroup);
        _ui_flag_modify(ui_TryAgainBtnCntr, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        _ui_flag_modify(ui_btScanLbl, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        _ui_flag_modify(ui_btEnablePanel, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_REMOVE);
        ScreenGroup[3] = EnableBtGroup;
        currentGroup = EnableBtGroup;
        for (int i = 0; i < btAudio.scanned_device_count; i++)
        {
            ui_btDevice[i] = style_device_button();
            ui_btDeviceLbl[i] = style_device_label(ui_btDevice[i], gotDevices[i].name);
            
            lv_obj_add_event_cb(ui_btDevice[i], ui_event_devNameEvents, LV_EVENT_ALL, &gotDevices[i]);
            lv_obj_add_style(ui_btDevice[i], &style_focus, LV_STATE_FOCUS_KEY);
        }
        
        lv_group_focus_obj(ui_btDevice[0]);        
        lv_group_add_obj(EnableBtGroup, ui_HiddenEnableBtScrBtn);
        checkListFlag = true;
    }

    if(lv_screen_active() == ui_BluetoothScreen)
    {
        syncBtScreen(false);
    }
}

void ui_event_btTryAgainBtn(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_PRESSED) {
        _ui_flag_modify(ui_TryAgainBtnCntr, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        _ui_flag_modify(ui_btScanLbl, LV_OBJ_FLAG_HIDDEN, _UI_MODIFY_FLAG_ADD);
        btAudio.start_bt_scan();
        // resetScanScrParams();
    }
    if(event_code == LV_EVENT_RELEASED) {
        _ui_screen_change(&ui_BluetoothScreen, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_BluetoothScreen_screen_init);
        navigatingWidgets = false;
        focusEnable = false;
        // syncBtScreen(false);
    }
}